import{_ as t,o,c as a,ag as r}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Week 9 Homework — Make the micro-app yours, start your pitch","description":"","frontmatter":{"source":"weeks/09-apis-and-secrets/homework.md"},"headers":[],"relativePath":"weeks/09-apis-and-secrets/homework.md","filePath":"weeks/09-apis-and-secrets/homework.md"}'),s={name:"weeks/09-apis-and-secrets/homework.md"};function i(n,e,h,d,c,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="week-9-homework--make-the-micro-app-yours-start-your-pitch" tabindex="-1">Week 9 Homework — Make the micro-app yours, start your pitch <a class="header-anchor" href="#week-9-homework--make-the-micro-app-yours-start-your-pitch" aria-label="Permalink to &quot;Week 9 Homework — Make the micro-app yours, start your pitch&quot;">​</a></h1><blockquote><p><strong>Core:</strong> about 5½ hours with project time, required. <strong>Stretch:</strong> optional. <strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before). This homework is the first half of <strong>Project 2: An AI Micro-App</strong> (<a href="./../../projects/ai-micro-app.html">brief</a>). Project 2 is graded once, at the end of week 10, with the <a href="./../../assessment/rubrics.html#project-2">Project 2 rubric</a> (15% of the course), so this week has no separate homework score. The reflection counts in <a href="./../../assessment/rubrics.html#assignments">Assignments</a>; the pitch draft becomes the pitch you submit next week, which counts there too.</p></blockquote><p><strong>AI-use key:</strong> 🟢 AI on: use AI, following the <a href="./../../resources/safe-loop.html">Safe Loop</a> · 🟡 AI limited: only in the way the task says · 🔴 AI off: close AI chat and turn off completions. <strong>Never</strong> paste a key or the contents of <code>.env</code> into any AI tool.</p><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><p>Only the reflection goes on Canvas this week; the app is submitted next week.</p><ul><li>☐ The app does its own job (system prompt, page text, styling), and the &quot;About this app&quot; section of <code>README.md</code> describes it (<a href="#1-make-it-fully-yours-about-2-h">task 1</a>)</li><li>☐ Your own <code>MAX_INPUT_LENGTH</code>, with one sentence in <code>PROMPTS.md</code> explaining it (<a href="#2-set-your-input-limit-and-try-each-error-about-1-h">task 2</a>)</li><li>☐ Empty input, too-long input and a missing key each tried on purpose, with what you saw noted in <code>PROMPTS.md</code></li><li>☐ A first draft of your capstone pitch, kept privately (not in your repository) (<a href="#3-capstone-pitch-a-first-draft-about-15-h">task 3</a>)</li><li>☐ <code>PROMPTS.md</code>: two or more entries with teach-backs (<a href="#4-promptsmd-about-30-min">task 4</a>)</li><li>☐ Week 9 reflection on Canvas (🔴 AI off) (<a href="#5-reflection-on-canvas-about-30-min">task 5</a>)</li><li>☐ Everything committed and synced; no <code>.env</code> on github.com; Codespace stopped</li></ul><table tabindex="0"><thead><tr><th>#</th><th>Task</th><th>AI use</th><th>About</th></tr></thead><tbody><tr><td>1</td><td>Make it fully yours (project build time)</td><td>🟢 AI on</td><td>2 h</td></tr><tr><td>2</td><td>Set your input limit and try each error</td><td>🟢 AI on; 🔴 AI off while <code>.env</code> is open</td><td>1 h</td></tr><tr><td>3</td><td>Capstone pitch: a first draft</td><td>🟡 AI limited</td><td>1.5 h</td></tr><tr><td>4</td><td><code>PROMPTS.md</code></td><td>🔴 AI off for teach-backs</td><td>30 min</td></tr><tr><td>5</td><td>Reflection on Canvas</td><td>🔴 AI off</td><td>30 min</td></tr><tr><td></td><td><strong>Total</strong></td><td></td><td><strong>about 5½ h</strong></td></tr></tbody></table><h2 id="core-required" tabindex="-1">Core (required) <a class="header-anchor" href="#core-required" aria-label="Permalink to &quot;Core (required)&quot;">​</a></h2><h3 id="1-make-it-fully-yours-about-2-h" tabindex="-1">1. Make it fully yours (about 2 h) <a class="header-anchor" href="#1-make-it-fully-yours-about-2-h" aria-label="Permalink to &quot;1. Make it fully yours (about 2 h)&quot;">​</a></h3><p>🟢 <strong>AI on:</strong> Copilot Chat in Ask mode, through the Safe Loop. Keep <code>.env</code> closed while Copilot is on.</p><ol><li><strong>Finish the job.</strong> Improve the system prompt in <code>lib/prompt.js</code> until all three checks from the lab pass, then the page text and styling. Optionally add an input, such as a dropdown for tone; if you do, the server must check it too (in <code>lib/validate.js</code>), because anyone can call <code>/api/ask</code> directly.</li><li><strong>Test locally before every push:</strong> <code>npm test</code>, then your three checks with <code>npm run dev</code>. A problem found in your Codespace takes minutes to fix; on next week&#39;s live site, much longer.</li><li><strong>Describe your version.</strong> Replace the &quot;About this app&quot; section of <code>README.md</code> with two or three sentences about what your app does and who it&#39;s for.</li><li><strong>Commit</strong> (with an <code>Assisted-by:</code> line if AI helped) and sync.</li></ol><h3 id="2-set-your-input-limit-and-try-each-error-about-1-h" tabindex="-1">2. Set your input limit and try each error (about 1 h) <a class="header-anchor" href="#2-set-your-input-limit-and-try-each-error-about-1-h" aria-label="Permalink to &quot;2. Set your input limit and try each error (about 1 h)&quot;">​</a></h3><p>🟢 <strong>AI on</strong> for reading code · 🔴 <strong>AI off</strong> while <code>.env</code> is open.</p><p>Your <code>/api/ask</code> route is public, so the server&#39;s input check is what protects your quota.</p><p><strong>Choose your limit (15 min).</strong> Open <code>public/lib/input.js</code> and set <code>MAX_INPUT_LENGTH</code> to a number that suits your app: a flashcard maker needs room for notes; an &quot;explain like I&#39;m five&quot; box doesn&#39;t. Because the browser and the server both import this file, one change updates both the counter and the server check. Add one sentence to <code>PROMPTS.md</code>: what you chose and why.</p><p><strong>Try each error on purpose (45 min).</strong> For each one, first predict what the page (or terminal) will show and which status code the browser will get; then try it with <code>npm run dev</code> running, and note in <code>PROMPTS.md</code> what you saw:</p><ul><li><p><strong>Empty input:</strong> press the button with an empty box.</p></li><li><p><strong>Too long:</strong> the page&#39;s box stops you typing past the limit, so send a long question straight to the server, as a stranger&#39;s script would. In a second terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fetch(&#39;http://localhost:3000/api/ask&#39;,{method:&#39;POST&#39;,headers:{&#39;Content-Type&#39;:&#39;application/json&#39;},body:JSON.stringify({question:&#39;a&#39;.repeat(5000)})}).then(r=&gt;r.text()).then(console.log)&quot;</span></span></code></pre></div></li><li><p><strong>Missing key</strong> (🔴 AI off while <code>.env</code> is open): put a <code>#</code> in front of the <code>LLM_API_KEY</code> line in <code>.env</code>, save, restart the server and ask a question. The page shows a friendly &quot;not set up&quot; message, and the technical detail stays in the terminal. Remove the <code>#</code>, save, close <code>.env</code> and restart. (If you keep your key in Codespaces secrets instead, skip this one and say so in <code>PROMPTS.md</code>.)</p></li></ul><p>Commit: for example <code>Set my input limit</code>. Next week you write automated tests that prove this limit holds.</p><h3 id="3-capstone-pitch-a-first-draft-about-15-h" tabindex="-1">3. Capstone pitch: a first draft (about 1.5 h) <a class="header-anchor" href="#3-capstone-pitch-a-first-draft-about-15-h" aria-label="Permalink to &quot;3. Capstone pitch: a first draft (about 1.5 h)&quot;">​</a></h3><p>🟡 <strong>AI limited:</strong> you write the pitch. You may ask an AI to <em>critique</em> it (&quot;What&#39;s unclear? What&#39;s too big?&quot;), but not to write it.</p><p>Your capstone starts in week 11, with an AI agent, from this pitch. The final version is due on Canvas <strong>72 hours before week 11 Studio A</strong>, so your instructor can reply <strong>Go</strong>, <strong>Go if you shrink it</strong> or <strong>Rethink</strong> before the studio. Drafting it now means next week&#39;s deploy can&#39;t squeeze it out.</p><ol><li>Read the <a href="./../../projects/capstone.html">Capstone brief</a> and browse <a href="./../../projects/capstone-ideas.html">Capstone Ideas</a> (30 min).</li><li>Draft the <a href="./../../projects/capstone.html#the-pitch">pitch template</a> (1 h): the problem and the user, a sketch of the main screen, which <strong>two or more</strong> feature types you&#39;ll include (pairs: three or more) from a server-side API call with a hidden key, a database with access rules, a data visualization and an external public API, what&#39;s out of scope, and your biggest risk with a plan B.</li></ol><p>Keep the draft in a private document, not a public repository. Keep it small: a capstone that works and that you can explain beats a big one that half-works. Pairing up? Agree on it this week.</p><h3 id="4-promptsmd-about-30-min" tabindex="-1">4. <code>PROMPTS.md</code> (about 30 min) <a class="header-anchor" href="#4-promptsmd-about-30-min" aria-label="Permalink to &quot;4. `PROMPTS.md` (about 30 min)&quot;">​</a></h3><p>At least two entries this week: your system-prompt work (your checks, the prompt, what you changed) and your input limit with the errors you tried. For every AI-written change you kept, add a <strong>teach-back</strong> (🔴 AI off: your own words, 2–3 sentences: what changed and why it works; <a href="./../../resources/safe-loop.html#teach-back">how</a>). Commits where AI helped carry an <code>Assisted-by:</code> line (<a href="./../../resources/safe-loop.html#the-assisted-by-line">how</a>). Never paste a key or <code>.env</code> contents into <code>PROMPTS.md</code>: it&#39;s public.</p><h3 id="5-reflection-on-canvas-about-30-min" tabindex="-1">5. Reflection on Canvas (about 30 min) <a class="header-anchor" href="#5-reflection-on-canvas-about-30-min" aria-label="Permalink to &quot;5. Reflection on Canvas (about 30 min)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> 150–300 words on Canvas, using the four headings of the <a href="./../../templates/REFLECTION.html">reflection template</a>, graded on specifics, not polish (<a href="./../../assessment/rubrics.html#reflections-and-peer-reviews">reflection rubric</a>).</p><p>Anchor it in one concrete moment: the line in your trace where the key is added, a status code you predicted wrong, or a system-prompt check that failed and what you changed. What do you now understand about the browser/server line that you didn&#39;t before Studio A?</p><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><p>Pick one. Commit before you start, so you can always go back.</p><ul><li><strong>Conversation memory.</strong> Let the user ask follow-up questions. Keep the conversation in the browser, send the last few messages with each request, and have the server check the <strong>total</strong> length, not just the latest message. Think about what happens to your quota and to privacy as conversations grow.</li><li><strong>Streaming replies.</strong> Make the answer appear word by word: send <code>&quot;stream&quot;: true</code> to the provider, return its stream from <code>api/ask.js</code>, and read it in the browser with <code>response.body.getReader()</code>, adding text with <code>textContent +=</code>. The dev server already passes streams through. Plan it with Copilot first; streaming formats differ slightly between providers.</li><li><strong>A local model with Ollama.</strong> On your own computer (not in a Codespace), install Ollama, pull a small model, run the starter locally (<a href="./../../setup/local-setup.html">Optional: set up your own computer</a>) and set <code>LLM_BASE_URL=http://localhost:11434/v1</code>. Useful models need a lot of memory; see the <a href="./../../TOOLS.html">Tool Handout</a>. Nothing leaves your machine, and there&#39;s no quota. What&#39;s the catch?</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up.</strong> Your micro-app answers a question in your Codespace with your own key, and <code>git status</code> doesn&#39;t list <code>.env</code>. Week 10 Studio A deploys exactly that. If it doesn&#39;t run yet, bring the exact error to office hours before Studio A.</p></div>',32)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
